// Cloudflare entry: OpenNext's worker for requests, plus a Cron Trigger that calls the tick route.
// @ts-ignore — generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { tickRequest } from "./lib/tick";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

export default {
  fetch: handler.fetch,
  scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) return console.error("amax: CRON_SECRET is not set; skipping tick");
    ctx.waitUntil(handler.fetch(tickRequest(env.CRON_SECRET), env, ctx));
  },
};
